import { gs, GlideRecord, GlideAggregate } from '@servicenow/glide'

/**
 * Calculates and updates budget totals (allocated, spent, available)
 * @param {GlideRecord} budgetRecord - The budget record to update
 */
export function calculateBudgetTotals(budgetRecord) {
    const budgetId = budgetRecord.getUniqueValue();

    // Calculate total allocated from budget allocations
    const allocatedAgg = new GlideAggregate('x_1962601_budget_t_budget_allocation');
    allocatedAgg.addQuery('budget', budgetId);
    allocatedAgg.addAggregate('SUM', 'allocated_amount');
    allocatedAgg.query();

    const totalAllocated = allocatedAgg.next() ? parseFloat(allocatedAgg.getAggregate('SUM', 'allocated_amount') || 0) : 0;

    // Calculate total spent from budget allocations
    const spentAgg = new GlideAggregate('x_1962601_budget_t_budget_allocation');
    spentAgg.addQuery('budget', budgetId);
    spentAgg.addAggregate('SUM', 'spent_amount');
    spentAgg.query();

    const totalSpent = spentAgg.next() ? parseFloat(spentAgg.getAggregate('SUM', 'spent_amount') || 0) : 0;

    // Calculate available amount
    const totalAvailable = totalAllocated - totalSpent;

    // Update the budget record
    budgetRecord.setValue('total_allocated', totalAllocated.toString());
    budgetRecord.setValue('total_spent', totalSpent.toString());
    budgetRecord.setValue('total_available', totalAvailable.toString());
    budgetRecord.update();

    gs.info(`Budget totals updated for ${budgetRecord.getDisplayValue()}: Allocated=${totalAllocated}, Spent=${totalSpent}, Available=${totalAvailable}`);
}
